  const chars = Array.from(text)
  const n = chars.length
  let i = 0
  let line = 1
  let col = 1

  const peek = (offset = 0) => chars[i + offset]

  const advance = () => {
    const c = chars[i]
    i++
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else {
      col++
    }
    return c
  }

  const fail = (message, pos) => {
    throw new LexError(message, pos.line, pos.col)
  }

  // Consumes a run of digits (as matched by `isDigit`) that may have a
  // single `_` between two digits of the run, and returns how many actual
  // digits were consumed.
  const scanDigitRun = (isDigit) => {
    let digits = 0
    let lastWasDigit = false
