      const c = peek()
      if (isDigit(c)) {
        advance()
        digits++
        lastWasDigit = true
      } else if (c === '_' && lastWasDigit && isDigit(peek(1))) {
        advance()
        lastWasDigit = false
      } else {
        break
      }
    }
    return digits
