    const startLine = line
    const startCol = col
    const startIdx = i
    let prefixError = false

    if (peek() === '0' && /[xXbBoO]/.test(peek(1) ?? '')) {
      const p = peek(1)
      advance()
      advance()
      let isDigit
      if (p === 'x' || p === 'X') isDigit = isHexDigit
      else if (p === 'b' || p === 'B') isDigit = isBinDigit
      else isDigit = isOctDigit
      const digits = scanDigitRun(isDigit)
      if (digits === 0) prefixError = true
    } else {
      scanDigitRun(isDecDigit)
      if (peek() === '.' && isDecDigit(peek(1))) {
        advance()
        scanDigitRun(isDecDigit)
      }
      if (peek() === 'e' || peek() === 'E') {
