    const startPos = { line, col }
    advance() // opening quote
    let value = ''
    while (true) {
      if (i >= n) fail('unterminated string', startPos)
      if (peek() === '\n') fail('newline in string', { line, col })
      if (peek() === '"') {
        advance()
        break
