      if (peek() === '\\') {
        const bsPos = { line, col }
        advance() // backslash
        if (i >= n) fail('unterminated string', startPos)
        if (peek() === '\n') fail('newline in string', { line, col })
        const e = peek()
        if (e === 'n') {
          value += '\n'
          advance()
        } else if (e === 't') {
          value += '\t'
          advance()
        } else if (e === 'r') {
          value += '\r'
          advance()
        } else if (e === '\\') {
          value += '\\'
          advance()
        } else if (e === '"') {
