    }
    return { line: startPos.line, col: startPos.col, kind: 'string', value }
  }

  const scanRawString = () => {
    const startPos = { line, col }
    advance() // r
    advance() // "
    let value = ''
    while (true) {
      if (i >= n) fail('unterminated string', startPos)
      if (peek() === '"') {
        advance()
        break
      }
      value += peek()
      advance()
    }
    return { line: startPos.line, col: startPos.col, kind: 'rawstring', value }
  }

  const tokens = []

  while (true) {
    // Skip whitespace and comments.
    while (i < n) {
      const c = peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        advance()
        continue
      }
      if (c === '/' && peek(1) === '/') {
        advance()
        advance()
        while (i < n && peek() !== '\n') advance()
        continue
      }
      if (c === '/' && peek(1) === '*') {
        const openPos = { line, col }
        advance()
        advance()
        let depth = 1
        while (depth > 0) {
          if (i >= n) fail('unterminated block comment', openPos)
          if (peek() === '/' && peek(1) === '*') {
            advance()
            advance()
            depth++
            continue
          }
          if (peek() === '*' && peek(1) === '/') {
            advance()
            advance()
            depth--
            continue
          }
          advance()
        }
        continue
      }
      break
    }
    if (i >= n) break

    const startLine = line
    const startCol = col
    const c = peek()

    if (isLetter(c)) {
      let s = ''
      while (i < n && isIdentPart(peek())) {
        s += peek()
        advance()
      }
