      tokens.push({ line: startLine, col: startCol, kind, text: s })
      continue
    }

    if (isDecDigit(c)) {
      tokens.push(scanNumber())
      continue
    }

    if (c === '"') {
      tokens.push(scanString())
      continue
    }

    if (c === 'r' && peek(1) === '"') {
      tokens.push(scanRawString())
      continue
    }

    const two = c + (peek(1) ?? '')
    if (TWO_CHAR_PUNCT.has(two)) {
