/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { tokenize, LexError } from './lexer.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function bodyOf(token) {
  if (token.kind === 'string' || token.kind === 'rawstring') {
    return JSON.stringify(token.value)
  }
  return token.text
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'tokens' && mode !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const source = readStdin()

  let tokens
  try {
    tokens = tokenize(source)
  } catch (err) {
    if (err instanceof LexError) {
      process.stderr.write(`error: ${err.line}:${err.col}: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  if (mode === 'tokens') {
    let out = ''
    for (const token of tokens) {
      out += `${token.line}:${token.col} ${token.kind} ${bodyOf(token)}\n`
    }
    process.stdout.write(out)
  } else {
    const counts = new Map(STAT_KINDS.map((k) => [k, 0]))
    for (const token of tokens) {
      counts.set(token.kind, counts.get(token.kind) + 1)
    }
    let out = ''
    for (const kind of STAT_KINDS) {
      out += `${kind} ${counts.get(kind)}\n`
    }
    out += `total ${tokens.length}\n`
    process.stdout.write(out)
  }

  process.exit(0)
}

